<script>const interruptedDrafts = new Map()</script>
<script setup>
import { reactive, ref, onMounted, onUnmounted } from 'vue'
import { request, upload, session } from '../api'
import { blankPost, postPayload, validatePost, campuses, contactLabels, today } from '../domain'
import State from '../components/State.vue'
const props=defineProps({id:String})
const form=reactive(blankPost()), photos=ref([]), errors=ref({}), error=ref(''), busy=ref(false), uploading=ref(false), loading=ref(!!props.id), quota=ref(null), success=ref(null), conflict=ref(false), loaded=ref(false)
const draftKey=(session.user?.id||'')+':'+(props.id||'new')
let etag='', pristine='', attempt=null
function dirty(){return pristine && JSON.stringify(postPayload(form))!==pristine && !success.value}
function beforeUnload(e){if(dirty()){e.preventDefault();e.returnValue=''}}
function leave(e){const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('#')&&dirty()&&!confirm('尚有未提交的内容，确定离开吗？'))e.preventDefault()}
async function load(){loading.value=true;loaded.value=false;error.value='';try {quota.value=await request('/users/me/post-quota');if(props.id){const p=await request('/posts/'+props.id);if(!p.can_edit)throw new Error('当前帖子不能编辑');Object.assign(form,postPayload(p));photos.value=(p.images||[]).map((key,i)=>({key,url:p.image_urls[i]}));etag=p.etag}pristine=JSON.stringify(postPayload(form));const draft=interruptedDrafts.get(draftKey);if(draft){Object.assign(form,draft.form);photos.value=draft.photos;etag=draft.etag;pristine=draft.pristine;attempt=draft.attempt;interruptedDrafts.delete(draftKey)}conflict.value=false;loaded.value=true}catch(e){error.value=e.message}finally{loading.value=false}}
async function addPhotos(e){const files=[...e.target.files];e.target.value='';if(files.length+photos.value.length>6){error.value='最多上传 6 张图片';return}uploading.value=true;error.value='';for(const file of files){const photo={name:file.name,file,key:null,url:URL.createObjectURL(file),error:''};photos.value.push(photo);await uploadPhoto(photo)}uploading.value=false}
async function uploadPhoto(photo){photo.error='';try{const data=await upload(photo.file);photo.key=data.object_key;syncImages()}catch(e){photo.error=e.message}}
async function retryPhoto(photo){uploading.value=true;await uploadPhoto(photo);uploading.value=false}
function syncImages(){form.images=photos.value.filter(p=>p.key).map(p=>p.key)}
function remove(i){const [photo]=photos.value.splice(i,1);if(photo.url?.startsWith('blob:'))URL.revokeObjectURL(photo.url);syncImages()}
function move(i,d){[photos.value[i],photos.value[i+d]]=[photos.value[i+d],photos.value[i]];syncImages()}
async function submit(){if(!loaded.value||busy.value||uploading.value||conflict.value)return;errors.value=validatePost(form);error.value='';if(Object.keys(errors.value).length)return;if(photos.value.some(p=>!p.key)){error.value='请先重试或移除上传失败的图片';return}const data=postPayload(form);const serialized=JSON.stringify(data);if(!attempt||attempt.body!==serialized)attempt={body:serialized,key:crypto.randomUUID()};busy.value=true;try{success.value=await request(props.id?'/posts/'+props.id:'/posts',{method:props.id?'PUT':'POST',data,etag:props.id?etag:undefined,key:props.id?undefined:attempt.key});pristine=serialized}catch(e){if(['AUTH_REQUIRED','TOKEN_EXPIRED','TOKEN_REVOKED','ACCOUNT_DISABLED','IDENTITY_UNVERIFIED','PASSWORD_CHANGE_REQUIRED'].includes(e.code))interruptedDrafts.set(draftKey,{form:data,photos:photos.value,etag,pristine,attempt});error.value=e.message;conflict.value=e.status===412;if(e.fields?.length)errors.value=Object.fromEntries(e.fields.map(f=>[f.field,f.message]));}finally{busy.value=false}}
function reload(){if(!dirty()||confirm('重新载入会替换尚未提交的修改，是否继续？'))load()}
onMounted(()=>{load();window.addEventListener('beforeunload',beforeUnload);document.addEventListener('click',leave,true)})
onUnmounted(()=>{const interrupted=dirty()&&(!session.user||session.forced);if(interrupted)interruptedDrafts.set(draftKey,{form:postPayload(form),photos:photos.value,etag,pristine,attempt});window.removeEventListener('beforeunload',beforeUnload);document.removeEventListener('click',leave,true);if(!interrupted)photos.value.forEach(p=>{if(p.url?.startsWith('blob:'))URL.revokeObjectURL(p.url)})})
</script>
<template><header class="page-heading"><span class="eyebrow">{{id?'EDIT POST':'SHARE A CLUE'}}</span><h1>{{id?'编辑并重新提交':'发布一条信息'}}</h1><p>{{id?'修改提交后暂时隐藏，审核通过后重新展示。':'你留下的线索，可能正是别人等待的消息。'}}</p></header><div v-if="success" class="panel success-panel"><span class="state-icon success">✓</span><h2>已提交审核</h2><p>审核结果会通过“我的通知”告诉你。</p><div class="row center"><a :href="'#post/'+success.id" class="primary">查看帖子</a><a href="#mine" class="secondary">我的帖子</a></div></div><State v-else-if="loading" loading/><State v-else-if="!loaded" :error="error" @retry="load"/><div v-else class="form-layout"><form class="panel" @submit.prevent="submit"><fieldset :disabled="busy||uploading"><h2>物品信息</h2><label>信息类型 <span class="required">*</span></label><div class="segmented type-picker"><label><input v-model="form.post_type" type="radio" value="lost">我丢失了物品</label><label><input v-model="form.post_type" type="radio" value="found">我拾到了物品</label></div><p class="field-error">{{errors.post_type}}</p><label>物品名称 *<input v-model="form.item_name" placeholder="例如：银色头戴式耳机"><small>{{[...form.item_name].length}} / 50</small><span class="field-error">{{errors.item_name}}</span></label><div class="two-col"><label>校区 *<select v-model="form.campus"><option value="">请选择校区</option><option v-for="(name,key) in campuses" :value="key">{{name}}</option></select><span class="field-error">{{errors.campus}}</span></label><label>{{form.post_type==='found'?'拾获地点':'丢失地点'}} *<input v-model="form.location" placeholder="具体到楼栋或区域"><span class="field-error">{{errors.location}}</span></label></div><div class="two-col"><label>{{form.post_type==='found'?'拾获日期':'丢失日期'}} *<input v-model="form.event_date" type="date" :max="today()"><span class="field-error">{{errors.event_date}}</span></label><label>时间精度 *<select v-model="form.time_precision"><option value="date">仅日期</option><option value="exact">具体时间</option><option value="range">同日时间段</option></select></label></div><div v-if="form.time_precision!=='date'" class="two-col"><label>{{form.time_precision==='range'?'开始时间':'具体时间'}} *<input v-model="form.event_time_start" type="time"><span class="field-error">{{errors.event_time_start}}</span></label><label v-if="form.time_precision==='range'">结束时间 *<input v-model="form.event_time_end" type="time"><span class="field-error">{{errors.event_time_end}}</span></label></div><label>物品描述 *<textarea v-model="form.description" rows="5" placeholder="描述颜色、外观、遗失或拾获经过等线索"></textarea><small>{{[...form.description].length}} / 300</small><span class="field-error">{{errors.description}}</span></label><hr><h2>物品照片 <small>选填</small></h2><p class="fine">最多 6 张，单张不超过 5 MB，支持 JPEG / PNG。第一张为封面。</p><div class="photo-editor"><div v-for="(photo,i) in photos" :key="photo.url" class="photo-tile"><img :src="photo.url" :alt="'照片 '+(i+1)"><div class="row"><button type="button" class="text-button" :disabled="i===0" @click="move(i,-1)" aria-label="前移照片">←</button><button type="button" class="text-button" @click="remove(i)">移除</button><button type="button" class="text-button" :disabled="i===photos.length-1" @click="move(i,1)" aria-label="后移照片">→</button></div><p v-if="photo.error" class="field-error">{{photo.error}}<button type="button" @click="retryPhoto(photo)">重试</button></p></div><label v-if="photos.length<6" class="upload-tile">＋<span>{{uploading?'上传中…':'添加照片'}}</span><input type="file" accept="image/jpeg,image/png" multiple @change="addPhotos"></label></div><hr><h2>联系方式</h2><p class="fine">至少填写一项。仅登录并有权查看此帖子的人可以看到。</p><div v-for="(c,i) in form.contact_methods" class="contact-editor"><select v-model="c.type" :aria-label="'联系方式类型 '+(i+1)"><option v-for="(name,key) in contactLabels" :value="key">{{name}}</option></select><input v-model="c.value" :aria-label="'联系方式 '+(i+1)" placeholder="请输入联系方式"><button class="text-button" type="button" @click="form.contact_methods.splice(i,1)">移除</button></div><button type="button" class="text-button" @click="form.contact_methods.push({type:'wechat',value:''})">＋ 添加联系方式</button><p class="field-error">{{errors.contact_methods}}</p><p v-if="error" role="alert" class="error">{{error}}</p><button v-if="conflict" type="button" class="secondary" @click="reload">重新查看最新版本</button><div class="form-actions"><button class="primary" :disabled="busy||uploading||conflict||(!id&&quota?.remaining===0)">{{busy?'提交中…':id?'提交重新审核':'提交审核'}}</button><a href="#mine" class="secondary">取消</a></div></fieldset></form><aside class="panel rules"><h3>{{id?'编辑提示':'今日发布额度'}}</h3><p class="quota-number" v-if="quota&&!id">{{quota.remaining}} <small>/ {{quota.limit}} 篇</small></p><p v-if="!id&&quota?.remaining===0" class="error">今日额度已用完，北京时间零点恢复。</p><p>新帖每天最多 3 篇，三端共用额度。</p><p>修改已有帖子不占新帖额度。已完成帖子编辑后保留完成状态。</p><hr><h3>让信息更有效</h3><p>清楚描述物品和地点，不公开完整证件号码等敏感信息。</p><p>请核实物品归属，再约定归还方式。</p></aside></div></template>
